      "https://www.metmuseum.org/ko/essays/the-birth-of-islam",
      "https://www.pbs.org/muhammad/timeline_html.shtml",
      "https://pressbooks.ulib.csuohio.edu/premodernmiddleeast/chapter/chapter-2-excerpts-from-the-quran/",
      "https://www.pbs.org/muhammad/essays/mattson.html"
    ]
  },
  "key_facts": [
